%[text] Scientific Programming - TCGA Ovarian Cancer dataset
%[text] 05 - Survival Models
%%
%[text] 1. Prepare clinical data for Cox regression \
clear;
clc;
close all;

load("results/cleaned_data.mat");

% Check available clinical variables
clinical_dfs.Properties.VariableNames' %[output:56bca578]

if ~exist("figures", "dir")
    mkdir("figures");
end
%[text] 
%[text] Collapse stage into II, III and IV:
stage = string(clinical_dfs.TUMOR_STAGE_2009);

stageCollapsed = strings(size(stage));

stageCollapsed(ismember(stage, ...
    ["IIA","IIB","IIC"])) = "II";

stageCollapsed(ismember(stage, ...
    ["IIIA","IIIB","IIIC"])) = "III";

stageCollapsed(stage == "IV") = "IV";

stageCollapsed(stageCollapsed == "") = missing;

stageCollapsed = categorical(stageCollapsed);

countcats(stageCollapsed) %[output:097e4710]
%[text] Some substages contained few patients, which would make separate Cox coefficient estimates unstable. Therefore, substages were collapsed into the broader Stage II, III and IV groups to increase the number of observations per category while preserving clinically interpretable disease stages.
%[text] 
%[text] Grade and residual disease:
%%\ Recode clinical missing values properly

gradeString = string(clinical_dfs.GRADE);
gradeString(gradeString == "NA") = missing;
grade = categorical(gradeString);

residualString = string(clinical_dfs.TUMOR_RESIDUAL_DISEASE);
residualString(residualString == "NA") = missing;
residual = categorical(residualString);
%%
%[text] 2\. Identify patients with complete information:
%%\ Complete-case cohort

time = clinical_dfs.DFS_MONTHS;

eventStatus = string(clinical_dfs.DFS_STATUS);

% Event = recurrence/progression
event = contains(eventStatus, "Recurred", ...
    'IgnoreCase', true) | ...
    contains(eventStatus, "Progressed", ...
    'IgnoreCase', true);

completeCases = ...
    ~isnan(time) & ...
    ~ismissing(stageCollapsed) & ...
    ~ismissing(grade) & ...
    ~ismissing(residual);

fprintf("Patients available for clinical Cox model: %d\n", ... %[output:group:786cb982] %[output:743e106a]
    sum(completeCases)); %[output:group:786cb982] %[output:743e106a]

fprintf("Events: %d\n", ... %[output:group:56d647c8] %[output:4d97efe0]
    sum(event(completeCases))); %[output:group:56d647c8] %[output:4d97efe0]

fprintf("Censored: %d\n", ... %[output:group:6cd672d1] %[output:9e28d7b5]
    sum(~event(completeCases))); %[output:group:6cd672d1] %[output:9e28d7b5]
%%
%[text] 3\. Encode clinical predictor
% Restrict to complete cases
time_cc = time(completeCases);
event_cc = event(completeCases);

stage_cc = stageCollapsed(completeCases);
grade_cc = grade(completeCases);
residual_cc = residual(completeCases);

% Check category order
categories(stage_cc) %[output:582acf38]
categories(grade_cc) %[output:8dd7edc6]
categories(residual_cc) %[output:01771265]
%%
%[text] 4\. Create dummy variables for Cox regression
%%\ Stage dummies
% Reference = Stage II

stageIII = double(stage_cc == 'III');
stageIV  = double(stage_cc == 'IV');

%%\ Grade dummy
% Reference = G2

gradeG3 = double(grade_cc == 'G3');

%%\ Residual disease dummies
% Reference = No Macroscopic disease

residual_1_10 = double(residual_cc == '1-10 mm');
residual_11_20 = double(residual_cc == '11-20 mm');
residual_gt20 = double(residual_cc == '>20mm');

%%\ Combine predictors

Xclinical = [ ...
    stageIII, ...
    stageIV, ...
    gradeG3, ...
    residual_1_10, ...
    residual_11_20, ...
    residual_gt20 ...
    ];

size(Xclinical) %[output:326fcce1]
%[text] Dummy variables were used to represent the categorical predictors. Stage II, G2, and no macroscopic residual disease were chosen as reference categories because they represent the less advanced or more favorable category within each predictor, making the resulting hazard ratios straightforward to interpret.
%%
%[text] 5\. Fit clinical Cox proportional hazards model
% MATLAB coxphfit uses censoring = 1 for censored observations
censoring = ~event_cc;

[b, logL, H, stats] = coxphfit( ...
    Xclinical, ...
    time_cc, ...
    'Censoring', censoring);

%%\ Hazard ratios and confidence intervals

hazardRatio = exp(b);

% 95% Wald confidence intervals.
% 1.96 is the approximate 97.5th percentile of the standard normal distribution.
CI_lower = exp(b - 1.96 * stats.se);
CI_upper = exp(b + 1.96 * stats.se);

predictorNames = { ...
    'Stage III vs II'; ...
    'Stage IV vs II'; ...
    'Grade G3 vs G2'; ...
    'Residual 1-10 mm vs none'; ...
    'Residual 11-20 mm vs none'; ...
    'Residual >20 mm vs none'};

coxResults = table( ...
    predictorNames, ...
    b, ...
    stats.se, ...
    hazardRatio, ...
    CI_lower, ...
    CI_upper, ...
    stats.p, ...
    'VariableNames', { ...
    'Predictor', ...
    'Beta', ...
    'SE', ...
    'HazardRatio', ...
    'CI_Lower', ...
    'CI_Upper', ...
    'PValue'});

disp(coxResults) %[output:7923a33b]
%[text] HR \> 1 - higher hazard of recurrence/progression compared with reference group
%[text] HR \< 1 - lower hazard
%[text] In the multivariable Cox model, Stage IV and residual disease of 1–10 mm or 11–20 mm were significantly associated with higher recurrence/progression hazard. Grade was not significantly associated with disease-free survival after adjustment for the other predictors. Residual disease showed the most consistent association across its categories.
%%\ Forest plot for clinical Cox model

figure; %[output:409cc2b0]

% Plot hazard ratios with 95% confidence intervals
errorbar( ... %[output:409cc2b0]
    coxResults.HazardRatio, ... %[output:409cc2b0]
    1:height(coxResults), ... %[output:409cc2b0]
    coxResults.HazardRatio - coxResults.CI_Lower, ... %[output:409cc2b0]
    coxResults.CI_Upper - coxResults.HazardRatio, ... %[output:409cc2b0]
    'horizontal', ... %[output:409cc2b0]
    'o', ... %[output:409cc2b0]
    'LineWidth', 1.5); %[output:409cc2b0]

hold on; %[output:409cc2b0]

% Reference line: HR = 1 means no difference from reference group
xline(1, '--', 'HR = 1'); %[output:409cc2b0]

% Predictor labels
yticks(1:height(coxResults)); %[output:409cc2b0]
yticklabels(coxResults.Predictor); %[output:409cc2b0]

% Put first predictor at the top
set(gca, 'YDir', 'reverse'); %[output:409cc2b0]

xlabel('Hazard ratio (95% CI)'); %[output:409cc2b0]
title('Clinical Cox model'); %[output:409cc2b0]

grid on; %[output:409cc2b0]
hold off; %[output:409cc2b0]

saveas(gcf, "figures/forestplot_clinicalcox.png"); %[output:409cc2b0]
%%
%[text] 6\. Check proportional hazards assumption
% Log-minus-log survival curves for stage

figure; %[output:93e52b96]
hold on; %[output:93e52b96]

stageGroups = categories(stage_cc);

for i = 1:numel(stageGroups)

    idx = stage_cc == stageGroups{i};

    % Kaplan-Meier estimate
    [S,tKM] = ecdf( ...
        time_cc(idx), ...
        'Censoring', censoring(idx), ...
        'Function','survivor');

    % Remove values that cannot be log-transformed
    valid = ...
        tKM > 0 & ...
        S > 0 & ...
        S < 1;

    plot( ... %[output:93e52b96]
        log(tKM(valid)), ... %[output:93e52b96]
        log(-log(S(valid))), ... %[output:93e52b96]
        'LineWidth',1.5); %[output:93e52b96]

end

xlabel('log(Time)'); %[output:93e52b96]
ylabel('log(-log(Survival))'); %[output:93e52b96]
title('Proportional hazards check: Stage'); %[output:93e52b96]
legend(stageGroups, 'Location','best'); %[output:93e52b96]
grid on; %[output:93e52b96]
hold off; %[output:93e52b96]

saveas(gcf, "figures/prophazards_stage.png"); %[output:93e52b96]
%[text] The log-minus-log survival curves for tumor stage were broadly parallel, with some deviation at earlier times. No strong violation of the proportional hazards assumption was evident from visual inspection.
%%\ Proportional hazards check: Grade

figure; %[output:53811537]
hold on; %[output:53811537]

gradeGroups = categories(grade_cc);

for i = 1:numel(gradeGroups)

    idx = grade_cc == gradeGroups{i};

    [S,tKM] = ecdf( ...
        time_cc(idx), ...
        'Censoring', censoring(idx), ...
        'Function','survivor');

    valid = ...
        tKM > 0 & ...
        S > 0 & ...
        S < 1;

    plot( ... %[output:53811537]
        log(tKM(valid)), ... %[output:53811537]
        log(-log(S(valid))), ... %[output:53811537]
        'LineWidth',1.5); %[output:53811537]

end

xlabel('log(Time)'); %[output:53811537]
ylabel('log(-log(Survival))'); %[output:53811537]
title('Proportional hazards check: Grade'); %[output:53811537]
legend(gradeGroups, 'Location','best'); %[output:53811537]
grid on; %[output:53811537]
hold off; %[output:53811537]
saveas(gcf, "figures/prophazards_grade.png"); %[output:53811537]
%[text] The log-minus-log survival curves for tumor grade were approximately parallel, suggesting that the proportional hazards assumption was reasonable for grade.
%%\ Proportional hazards check: Residual disease

figure; %[output:5e8496ce]
hold on; %[output:5e8496ce]

residualGroups = categories(residual_cc);

for i = 1:numel(residualGroups)

    idx = residual_cc == residualGroups{i};

    [S,tKM] = ecdf( ...
        time_cc(idx), ...
        'Censoring', censoring(idx), ...
        'Function','survivor');

    valid = ...
        tKM > 0 & ...
        S > 0 & ...
        S < 1;

    plot( ... %[output:5e8496ce]
        log(tKM(valid)), ... %[output:5e8496ce]
        log(-log(S(valid))), ... %[output:5e8496ce]
        'LineWidth',1.5); %[output:5e8496ce]

end

xlabel('log(Time)'); %[output:5e8496ce]
ylabel('log(-log(Survival))'); %[output:5e8496ce]
title('Proportional hazards check: Residual disease'); %[output:5e8496ce]
legend(residualGroups, 'Location','best'); %[output:5e8496ce]
grid on; %[output:5e8496ce]
hold off; %[output:5e8496ce]
saveas(gcf, "figures/prophazards_residualdisease.png"); %[output:5e8496ce]
%[text] The log-minus-log survival curves for residual disease were generally similar in shape, although some crossing and early-time deviations were present. No severe violation of the proportional hazards assumption was evident visually, but the assumption appears less clear than for grade. 
%%
%[text] 7\. Apparent C-index of clinical Cox model
% Linear predictor from Cox model
riskScore = Xclinical * b;

concordant = 0;
comparable = 0;

n = numel(time_cc);

for i = 1:n-1
    for j = i+1:n

        % Patient i had an observed event before patient j
        if event_cc(i) && time_cc(i) < time_cc(j)

            comparable = comparable + 1;

            if riskScore(i) > riskScore(j)
                concordant = concordant + 1;

            elseif riskScore(i) == riskScore(j)
                concordant = concordant + 0.5;
            end

            % Patient j had an observed event before patient i
        elseif event_cc(j) && time_cc(j) < time_cc(i)

            comparable = comparable + 1;

            if riskScore(j) > riskScore(i)
                concordant = concordant + 1;

            elseif riskScore(j) == riskScore(i)
                concordant = concordant + 0.5;
            end

        end
    end
end

cIndex = concordant / comparable;

fprintf("Clinical Cox apparent C-index: %.3f\n", cIndex); %[output:13bf07bb]
fprintf("Comparable patient pairs: %d\n", comparable); %[output:23f1fb93]
%[text] The clinical Cox model achieved an apparent C-index of 0.603 across 41,372 comparable patient pairs, indicating modest ability to rank patients by disease-free survival risk. Because this value was calculated on the same cohort used to fit the model, it likely overestimates performance on unseen patients.
%%
%[text] 8\. 5-fold cross validated C-index for clinical Cox model
%[text] Five-fold cross-validation was chosen as a compromise between retaining a large training set and maintaining sufficiently sized test folds. With 346 patients, each test fold contains approximately 69 patients. The same five-fold structure was used consistently throughout the predictive analyses.
rng(1);

cvCox = cvpartition(event_cc, 'KFold', 5);

cvRiskScore = nan(size(time_cc));

for fold = 1:cvCox.NumTestSets

    trainIdx = training(cvCox, fold);
    testIdx  = test(cvCox, fold);

    Xtrain = Xclinical(trainIdx,:);
    Xtest  = Xclinical(testIdx,:);

    timeTrain = time_cc(trainIdx);
    censorTrain = ~event_cc(trainIdx);

    %%\ Fit Cox model on training fold only

    bFold = coxphfit( ...
        Xtrain, ...
        timeTrain, ...
        'Censoring', censorTrain);

    %%\ Predict risk for held-out patients

    cvRiskScore(testIdx) = Xtest * bFold;

end
%[text] 
%%\ Cross-validated C-index

concordant = 0;
comparable = 0;

n = numel(time_cc);

for i = 1:n-1
    for j = i+1:n

        % Patient i had an observed event before patient j
        if event_cc(i) && time_cc(i) < time_cc(j)

            comparable = comparable + 1;

            if cvRiskScore(i) > cvRiskScore(j)
                concordant = concordant + 1;

            elseif cvRiskScore(i) == cvRiskScore(j)
                concordant = concordant + 0.5;
            end

            % Patient j had an observed event before patient i
        elseif event_cc(j) && time_cc(j) < time_cc(i)

            comparable = comparable + 1;

            if cvRiskScore(j) > cvRiskScore(i)
                concordant = concordant + 1;

            elseif cvRiskScore(j) == cvRiskScore(i)
                concordant = concordant + 0.5;
            end

        end
    end
end

cvCIndex = concordant / comparable;

fprintf("Clinical Cox 5-fold CV C-index: %.3f\n", cvCIndex); %[output:8255d611]
fprintf("Comparable patient pairs: %d\n", comparable); %[output:18220ff7]
%[text] The clinical Cox model achieved a 5-fold cross-validated C-index of 0.576, compared with an apparent C-index of 0.603. This reduction indicates some optimism in the training-set estimate. Overall, the clinical variables provided modest discrimination of disease-free survival risk on unseen patients.
%[text] Clinical-only baseline: 5-fold CV C-index: 0.576
%%
%[text] Clinical + expression Cox model
%[text] 9\. Sensitivity analysis: 5, 10 and 20 expression PCs
%[text] The models were evaluated with 5, 10 and 20 PCs as a sensitivity analysis across increasing levels of expression-model complexity. These values were not assumed to be optimal: 5 PCs provided a low-dimensional representation, 10 represented an intermediate model, and 20 tested whether retaining additional expression structure improved prediction. The aim was to assess dependence on model complexity rather than to search exhaustively for the best PC count.
rng(1);

% Expression data for the same complete-case patients
Xexpr = expression_dfs(:, completeCases)';

% Number of PCs to compare
nPC_values = [5 10 20];

cvCombined = cvpartition(event_cc, 'KFold', 5);

cvRiskCombined = nan(numel(time_cc), numel(nPC_values));

for fold = 1:cvCombined.NumTestSets

    trainIdx = training(cvCombined, fold);
    testIdx  = test(cvCombined, fold);

    %%\ Clinical data

    XclinicalTrain = Xclinical(trainIdx,:);
    XclinicalTest  = Xclinical(testIdx,:);

    %%\ Expression data

    XexprTrain = Xexpr(trainIdx,:);
    XexprTest  = Xexpr(testIdx,:);

    %%\ Variance filtering using training data only

    geneVarianceTrain = var(XexprTrain, 0, 1);

    % Remove lowest 20% of genes by variance
    varianceThreshold = prctile(geneVarianceTrain, 20);

    keepGenes = geneVarianceTrain > varianceThreshold;

    XexprTrainFiltered = XexprTrain(:, keepGenes);
    XexprTestFiltered  = XexprTest(:, keepGenes);

    %%\ PCA fitted on training expression only

    [coeffExpr, scoreTrainExpr, ~, ~, ~, muExpr] = ...
        pca(XexprTrainFiltered);

    % Project held-out patients into training PCA space
    XexprTestCentered = XexprTestFiltered - muExpr;

    scoreTestExpr = ...
        XexprTestCentered * coeffExpr;

    %%\ Fit combined models for different PC counts

    for j = 1:numel(nPC_values)

        nPC = nPC_values(j);

        % Combined clinical + expression predictors
        XtrainCombined = [ ...
            XclinicalTrain, ...
            scoreTrainExpr(:,1:nPC)];

        XtestCombined = [ ...
            XclinicalTest, ...
            scoreTestExpr(:,1:nPC)];

        %%\ Fit Cox model on training fold only

        bCombined = coxphfit( ...
            XtrainCombined, ...
            time_cc(trainIdx), ...
            'Censoring', ~event_cc(trainIdx));

        %%\ Risk score for held-out patients

        cvRiskCombined(testIdx,j) = ...
            XtestCombined * bCombined;

    end
end
%[text] The 20% variance filter was selected from the earlier variance-retention analysis, where it provided a moderate reduction in low-variance genes while retaining approximately 94.8% of total expression variance. Within cross-validation, the threshold was recalculated using training samples only to prevent information leakage.
%%\ Evaluate clinical + expression models

for j = 1:numel(nPC_values) %[output:group:63df96ae]

    riskScore = cvRiskCombined(:,j);

    concordant = 0;
    comparable = 0;

    n = numel(time_cc);

    for i = 1:n-1
        for k = i+1:n

            if event_cc(i) && time_cc(i) < time_cc(k)

                comparable = comparable + 1;

                if riskScore(i) > riskScore(k)
                    concordant = concordant + 1;

                elseif riskScore(i) == riskScore(k)
                    concordant = concordant + 0.5;
                end

            elseif event_cc(k) && time_cc(k) < time_cc(i)

                comparable = comparable + 1;

                if riskScore(k) > riskScore(i)
                    concordant = concordant + 1;

                elseif riskScore(k) == riskScore(i)
                    concordant = concordant + 0.5;
                end

            end

        end
    end

    cIndexCombined = concordant / comparable;

    fprintf( ... %[output:0c90fc8c]
        "Clinical + %d expression PCs: CV C-index = %.3f\n", ... %[output:0c90fc8c]
        nPC_values(j), cIndexCombined); %[output:0c90fc8c]

end %[output:group:63df96ae]

fprintf("Clinical-only baseline: CV C-index = %.3f\n", ... %[output:group:848485ea] %[output:658d9714]
    cvCIndex); %[output:group:848485ea] %[output:658d9714]
%[text] Adding expression-derived features had mixed effects on cross-validated performance. Models using 5 or 10 expression PCs performed slightly worse than the clinical-only model, whereas the model using 20 PCs increased the C-index from 0.576 to 0.597. This suggests that gene-expression data may contain additional prognostic information, but the improvement was modest and depended on the number of retained PCs.
%%
%[text] 10\. Sensitivity analysis across 50 repeated CV splits
%[text] Fifty repetitions were used as a pragmatic stability analysis to reduce dependence on a single random five-fold partition. The number 50 was not treated as statistically optimal; it provided enough alternative splits to assess whether the observed pattern was reproducible without excessive computation.
% Compare clinical-only vs clinical + 5, 10 and 20 expression PCs

nRepeats = 50;
nPC_values = [5 10 20];

cIndexClinicalRep = zeros(nRepeats,1);
cIndexCombinedRep = zeros(nRepeats,numel(nPC_values));

for r = 1:nRepeats

    rng(r);

    cvRep = cvpartition(event_cc, 'KFold', 5);

    riskClinical = nan(size(time_cc));
    riskCombined = nan(numel(time_cc), numel(nPC_values));

    for fold = 1:cvRep.NumTestSets

        trainIdx = training(cvRep, fold);
        testIdx  = test(cvRep, fold);

        %%\ Clinical-only model

        bClinical = coxphfit( ...
            Xclinical(trainIdx,:), ...
            time_cc(trainIdx), ...
            'Censoring', ~event_cc(trainIdx));

        riskClinical(testIdx) = ...
            Xclinical(testIdx,:) * bClinical;


        %%\ Expression preprocessing inside training fold

        XexprTrain = Xexpr(trainIdx,:);
        XexprTest  = Xexpr(testIdx,:);

        % Variance filter fitted only on training data
        geneVarianceTrain = var(XexprTrain, 0, 1);

        varianceThreshold = ...
            prctile(geneVarianceTrain, 20);

        keepGenes = ...
            geneVarianceTrain > varianceThreshold;

        XexprTrainFiltered = ...
            XexprTrain(:,keepGenes);

        XexprTestFiltered = ...
            XexprTest(:,keepGenes);


        %%\ PCA fitted only on training expression data

        [coeffExpr, scoreTrainExpr, ~, ~, ~, muExpr] = ...
            pca(XexprTrainFiltered);

        scoreTestExpr = ...
            (XexprTestFiltered - muExpr) * coeffExpr;


        %%\ Combined models with different PC numbers

        for p = 1:numel(nPC_values)

            nPC = nPC_values(p);

            XtrainCombined = [ ...
                Xclinical(trainIdx,:), ...
                scoreTrainExpr(:,1:nPC)];

            XtestCombined = [ ...
                Xclinical(testIdx,:), ...
                scoreTestExpr(:,1:nPC)];

            bCombined = coxphfit( ...
                XtrainCombined, ...
                time_cc(trainIdx), ...
                'Censoring', ~event_cc(trainIdx));

            riskCombined(testIdx,p) = ...
                XtestCombined * bCombined;

        end
    end


    %%\ Clinical-only C-index

    concordant = 0;
    comparable = 0;

    n = numel(time_cc);

    for i = 1:n-1
        for j = i+1:n

            if event_cc(i) && time_cc(i) < time_cc(j)

                comparable = comparable + 1;

                if riskClinical(i) > riskClinical(j)
                    concordant = concordant + 1;
                elseif riskClinical(i) == riskClinical(j)
                    concordant = concordant + 0.5;
                end

            elseif event_cc(j) && time_cc(j) < time_cc(i)

                comparable = comparable + 1;

                if riskClinical(j) > riskClinical(i)
                    concordant = concordant + 1;
                elseif riskClinical(j) == riskClinical(i)
                    concordant = concordant + 0.5;
                end
            end

        end
    end

    cIndexClinicalRep(r) = ...
        concordant / comparable;


    %%\ Combined-model C-indices

    for p = 1:numel(nPC_values)

        riskScore = riskCombined(:,p);

        concordant = 0;
        comparable = 0;

        for i = 1:n-1
            for j = i+1:n

                if event_cc(i) && time_cc(i) < time_cc(j)

                    comparable = comparable + 1;

                    if riskScore(i) > riskScore(j)
                        concordant = concordant + 1;
                    elseif riskScore(i) == riskScore(j)
                        concordant = concordant + 0.5;
                    end

                elseif event_cc(j) && time_cc(j) < time_cc(i)

                    comparable = comparable + 1;

                    if riskScore(j) > riskScore(i)
                        concordant = concordant + 1;
                    elseif riskScore(j) == riskScore(i)
                        concordant = concordant + 0.5;
                    end
                end

            end
        end

        cIndexCombinedRep(r,p) = ...
            concordant / comparable;

    end
end
%[text] 
%%\ Summarize sensitivity analysis

fprintf("\nClinical-only median C-index: %.3f\n", ... %[output:group:1aab31b8] %[output:9b148659]
    median(cIndexClinicalRep)); %[output:group:1aab31b8] %[output:9b148659]

for p = 1:numel(nPC_values) %[output:group:92e79b56]

    differenceRep = ...
        cIndexCombinedRep(:,p) - cIndexClinicalRep;

    fprintf("\nClinical + %d PCs\n", nPC_values(p)); %[output:8d5d1148] %[output:092eefaa] %[output:73c21ad7]

    fprintf("Median C-index: %.3f\n", ... %[output:4f0e04de] %[output:3d456ec8] %[output:2f0cfbb8]
        median(cIndexCombinedRep(:,p))); %[output:4f0e04de] %[output:3d456ec8] %[output:2f0cfbb8]

    fprintf("Median difference vs clinical: %.3f\n", ... %[output:734b3290] %[output:836a71d3] %[output:444784e9]
        median(differenceRep)); %[output:734b3290] %[output:836a71d3] %[output:444784e9]

    fprintf("Better than clinical-only in %.1f%% of repetitions\n", ... %[output:793a6b36] %[output:9560cafe] %[output:93b0b7c3]
        100 * mean(differenceRep > 0)); %[output:793a6b36] %[output:9560cafe] %[output:93b0b7c3]

end %[output:group:92e79b56]
%[text] Across 50 repeated five-fold cross-validation splits, the effect of adding expression depended on the number of retained PCs. Models with 5 or 10 PCs generally performed worse than the clinical-only model, whereas the 20-PC model had a slightly higher median C-index (0.571 vs 0.566) and outperformed the clinical-only model in 72% of repetitions. Thus, expression may contribute additional prognostic information, but the improvement was small and dependent on the chosen feature representation.

